func:
node.status({fill:"blue",shape:"dot",text:"Входные данные"});
const userQuery = msg.payload?.query || msg.payload?.message || msg.payload || '';
if (!userQuery || typeof userQuery !== 'string' || userQuery.trim() === '') {
    node.warn('[REWOO][INPUT] Пустой запрос. Прерывание.');
    node.status({fill:"red",shape:"ring",text:"Ошибка: Пусто"});
    return null;
}

node.warn(`[REWOO][INPUT] Принят запрос: "${userQuery.substring(0, 80)}...`);
msg.context = {
    userQuery: userQuery.trim(),
    timestamp: new Date().toISOString(),
    plan: null,
    observations: {},
    finalAnswer: null,
    pdfPath: null
};
msg.payload = userQuery.trim();
return msg;

node.status({fill:"blue",shape:"dot",text:"MCP Init"});
node.warn('[REWOO][MCP] Инициализация сессии...');
msg.payload = {
    "jsonrpc": "2.0", "id": 1, "method": "initialize",
    "params": { "protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": { "name": "node-red-rewoo", "version": "3.0" } }
};
msg.headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream" };
return msg;

const sessionId = msg.headers && (msg.headers['mcp-session-id'] || msg.headers['Mcp-Session-Id']);
if (sessionId) {
    msg._mcpSessionId = sessionId;
    node.warn(`[REWOO][MCP] Session ID получен: ${sessionId}`);
} else {
    node.warn('[REWOO][MCP] Session ID НЕ найден!');
}

node.status({fill:"blue",shape:"dot",text:"Получение инструментов"});
msg.payload = { "jsonrpc": "2.0", "id": 2, "method": "tools/list", "params": {} };
msg.headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream" };
if (sessionId) msg.headers['mcp-session-id'] = sessionId;
return msg;

node.status({fill:"yellow",shape:"dot",text:"Плановик: Промпт"});

function parseMcp(raw) {
    if (typeof raw === 'object' && raw !== null) return raw;
    if (typeof raw !== 'string') return null;
    const m = raw.match(/^data:\s*(\{[\s\S]*\})\s*$/m);
    if (m) { try { return JSON.parse(m[1]); } catch(e) {} }
    try { return JSON.parse(raw.trim()); } catch(e) {}
    return null;
}

const mcpData = parseMcp(msg.payload);
const mcpTools = mcpData?.result?.tools || [];
node.warn(`[REWOO][PLANNER] Доступно MCP инструментов: ${mcpTools.length}`);

const toolsDesc = mcpTools.map(t => `- ${t.name}: ${t.description || 'Нет описания'}. Параметры: ${JSON.stringify(t.inputSchema?.properties || {})}`).join('\n');

const PLANNER_PROMPT = `Ты — Плановик (Planner) в архитектуре ReWOO. Составь план вызова инструментов.
ПРАВИЛА:
1. НЕ отвечай на вопрос. ТОЛЬКО план.
2. Для передачи ID от предыдущего шага используй синтаксис "#E1", "#E2" и т.д.
3. Формат ответа — СТРОГО JSON массив без markdown.

ИНСТРУМЕНТЫ:
${toolsDesc}

ФОРМАТ:
[
  {"step": "#E1", "tool": "имя", "arguments": {"arg": "значение"}}
]`;

msg.payload = {
    model: "T-lite-it-2.1-Q4_K_M.gguf",
    max_tokens: 10000, temperature: 0.0,
    messages: [
        { role: "system", content: PLANNER_PROMPT },
        { role: "user", content: msg.context.userQuery }
    ]
};

node.warn('[REWOO][PLANNER] Запрос к LLM отправлен...');
return msg;

let raw = msg.payload?.choices?.[0]?.message?.content || '';
node.warn(`[REWOO][PLANNER] Сырой ответ LLM:\n${raw}`);
let plan = [];

try {
    let clean = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    const jsonMatch = clean.match(/\[[\s\S]*\]/);
    if (jsonMatch) clean = jsonMatch[0];
    plan = JSON.parse(clean);
} catch (e) {
    node.error(`[REWOO][PLANNER] Ошибка парсинга JSON плана!`, msg);
}

if (!Array.isArray(plan) || plan.length === 0) {
    node.warn("[REWOO][PLANNER] План пуст. Передаем в Solver без данных.");
    plan = [];
}

msg.context.plan = plan;
msg._planSteps = plan;
msg._currentStepIndex = 0;
msg._observations = {};

node.status({fill:"green",shape:"dot",text:`План: ${plan.length} шагов`});
node.warn(`[REWOO][PLANNER] Успешно распарсен план на ${plan.length} шагов.`);
return msg;

if (msg._currentStepIndex < msg._planSteps.length) {
    const step = msg._planSteps[msg._currentStepIndex];
    node.status({fill:"blue",shape:"dot",text:`Worker: Шаг ${msg._currentStepIndex+1}/${msg._planSteps.length}`});
    node.warn(`[REWOO][WORKER] Запуск шага ${step.step} -> ${step.tool}`);
    return [msg, null]; 
} else {
    node.status({fill:"green",shape:"ring",text:"Worker: Завершено"});
    node.warn(`[REWOO][WORKER] Все инструменты выполнены. Собрано данных: ${Object.keys(msg._observations).length}`);
    return [null, msg];
}

const step = msg._planSteps[msg._currentStepIndex];
let resolvedArgs = {};
if (step.arguments) {
    for (let key in step.arguments) {
        let val = String(step.arguments[key]);
        if (val.startsWith('#E') && msg._observations[val]) {
            resolvedArgs[key] = msg._observations[val];
        } else {
            resolvedArgs[key] = step.arguments[key];
        }
    }
}

node.warn(`[REWOO][WORKER] Аргументы для ${step.tool}: ${JSON.stringify(resolvedArgs).substring(0, 200)}`);
msg._currentStepId = step.step;
msg.payload = {
    jsonrpc: "2.0", id: Date.now(), method: "tools/call",
    params: { name: step.tool, arguments: resolvedArgs }
};
msg.headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream" };
if (msg._mcpSessionId) msg.headers['mcp-session-id'] = msg._mcpSessionId;
return msg;

function parseMcp(raw) {
    if (typeof raw === 'object' && raw !== null) return raw;
    if (typeof raw !== 'string') return null;
    const m = raw.match(/^data:\s*(\{[\s\S]*\})\s*$/m);
    if (m) { try { return JSON.parse(m[1]); } catch(e) {} }
    try { return JSON.parse(raw.trim()); } catch(e) {}
    return null;
}

const parsed = parseMcp(msg.payload);
let resultText = '';
if (parsed?.result?.content?.[0]?.text) {
    resultText = parsed.result.content[0].text;
} else {
    resultText = JSON.stringify(parsed?.result || parsed || 'no result');
}

msg._observations[msg._currentStepId] = resultText;
node.warn(`[REWOO][WORKER] Результат ${msg._currentStepId} получен (длина: ${resultText.length} символов)`);

msg._currentStepIndex++;
return msg;

node.status({fill:"yellow",shape:"dot",text:"Решатель: Промпт"});

const SOLVER_PROMPT = `Ты — Решатель (Solver). Проанализируй результаты инструментов и дай профессиональный ответ.
Формат: Markdown (заголовки ##, таблицы |, списки). Язык: Русский.`;

let obsText = 'Нет данных (план был пуст).';
if (Object.keys(msg._observations).length > 0) {
    obsText = Object.entries(msg._observations).map(([k, v]) => `--- ${k} ---\n${v}`).join('\n\n');
}

node.warn(`[REWOO][SOLVER] Собрано текста с данными: ${obsText.length} символов`);

msg.payload = {
    model: "T-lite-it-2.1-Q4_K_M.gguf",
    max_tokens: 10000, temperature: 0.2,
    messages: [
        { role: "system", content: SOLVER_PROMPT },
        { role: "user", content: `Вопрос: ${msg.context.userQuery}\n\nДанные (Observations):\n${obsText}\n\nНапиши финальный ответ.` }
    ]
};
node.warn('[REWOO][SOLVER] Запрос к LLM отправлен...');
return msg;

const finalText = msg.payload?.choices?.[0]?.message?.content || 'Ответ не получен от Solver';
msg.context.finalAnswer = finalText;
msg.payload = finalText;

node.status({fill:"green",shape:"dot",text:`Ответ готов (${finalText.length} сим.)`});
node.warn(`[REWOO][SOLVER] Финальный текст получен. Длина: ${finalText.length}`);
return msg;

node.status({fill:"blue",shape:"dot",text:"Сохранение TXT"});
msg.filename = "/tmp/schedule_answer_text.txt";
msg.payload = msg.context.finalAnswer || '';
return msg;

node.log('[restore_payload] Восстанавливаем оригинальный payload');
msg.payload = msg._originalPayload;
delete msg._originalPayload;
return msg;

node.log('[pdf_success] PDF успешно создан! Путь: ' + msg._pdfPath);
msg.context.pdfPath = msg._pdfPath;
msg.payload = {
    success: true,
    pdfPath: msg._pdfPath,
    userQuery: msg.context.userQuery,
    finalAnswer: msg.context.finalAnswer,
    agentsUsed: {
        agent1: msg.context.routerDecision?.useAgent1 || false,
        agent2: msg.context.routerDecision?.useAgent2 || false
    },
    routerReasoning: msg.context.routerDecision?.reasoning
};
return msg;

node.error('[pdf_error] Ошибка генерации PDF (stderr): ' + JSON.stringify(msg.payload));
msg.payload = {
    success: false,
    error: 'Ошибка генерации PDF: ' + JSON.stringify(msg.payload),
    finalAnswer: msg.context.finalAnswer
};
return msg;

node.warn('[pdf_timeout] ТАЙМАУТ генерации PDF (процесс завис)');
msg.payload = {
    success: false,
    error: 'Таймаут генерации PDF (процесс убит после 120с)',
    finalAnswer: msg.context?.finalAnswer
};
return msg;
